UPDATE research_funds SET catalogue_uid = (SELECT m.new_uid FROM research_fund_directory_uid_moves m WHERE m.old_uid = research_funds.catalogue_uid) WHERE catalogue_uid IN (SELECT old_uid FROM research_fund_directory_uid_moves WHERE old_uid NOT IN (SELECT uid FROM research_fund_directory));
UPDATE raise_prospects SET research_fund_uid = (SELECT m.new_uid FROM research_fund_directory_uid_moves m WHERE m.old_uid = raise_prospects.research_fund_uid) WHERE research_fund_uid IN (SELECT old_uid FROM research_fund_directory_uid_moves WHERE old_uid NOT IN (SELECT uid FROM research_fund_directory));
UPDATE research_project_subjects SET directory_uid = (SELECT m.new_uid FROM research_fund_directory_uid_moves m WHERE m.old_uid = research_project_subjects.directory_uid) WHERE kind = 'fund' AND directory_uid IN (SELECT old_uid FROM research_fund_directory_uid_moves WHERE old_uid NOT IN (SELECT uid FROM research_fund_directory));
